/*═══════════════════════════════════════
  REGION: 页面上方正中间 收起/展开按钮 非悬浮版
═══════════════════════════════════════*/

:root {
  --tutu-ui-scale: 1;

  --tutu-toggle-base-size: 92px;
  --tutu-toggle-base-top-gap: 4px;
  --tutu-toggle-base-page-gap: 8px;

  --tutu-toggle-size: calc(var(--tutu-toggle-base-size) * var(--tutu-ui-scale));
  --tutu-toggle-top-gap: calc(var(--tutu-toggle-base-top-gap) * var(--tutu-ui-scale));
  --tutu-toggle-page-gap: calc(var(--tutu-toggle-base-page-gap) * var(--tutu-ui-scale));


  /* 给 overlay 页面用：按钮区域总高度 */
  --tutu-panel-offset: calc(
    var(--tutu-toggle-top-gap) +
    var(--tutu-toggle-size) +
    var(--tutu-toggle-page-gap)
  );
}

/* body 不要白底，否则透明 PNG 后面会有白色长条 */
body {
  background: transparent !important;
}

/*
  重点：
  按钮不再 fixed！
  它在正常文档流里，占据真实高度。
*/

#tutuPanelToggle {
  position: relative;
  left: 50%;

  /* 不要 999999，不然它永远压过聊天页 */
  z-index: 2000;


  width: var(--tutu-toggle-size);
  height: var(--tutu-toggle-size);

  margin-top: var(--tutu-toggle-top-gap) !important;
  margin-bottom: var(--tutu-toggle-page-gap) !important;

  padding: 0 !important;
  border: 0 !important;
  outline: none !important;

  background: transparent !important;
  background-color: transparent !important;
  box-shadow: none !important;
  filter: none !important;

  appearance: none;
  -webkit-appearance: none;

  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;

  display: flex;
  align-items: center;
  justify-content: center;

  transform: translateX(-50%);
}

#tutuPanelToggle,
#tutuPanelToggle:hover,
#tutuPanelToggle:focus,
#tutuPanelToggle:active {
  background: transparent !important;
  background-color: transparent !important;
  box-shadow: none !important;
  outline: none !important;
  -webkit-tap-highlight-color: transparent;
}

#tutuPanelToggle img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
  pointer-events: none;
  background: transparent !important;
}

#tutuPanelToggle:active img {
  transform: scale(0.94);
}

/* 打开二级页时，如果配置为隐藏按钮 */
body.tutu-hide-toggle-on-overlay.overlay-open #tutuPanelToggle {
  display: none !important;
}

/* 如果按钮不隐藏，就继续显示在自己的顶部区域 */
body.overlay-open:not(.tutu-hide-toggle-on-overlay) #tutuPanelToggle {
  display: flex !important;
}

/*
  主页面不需要再 margin-top。
  因为按钮自己已经占了上方空间。
*/
#appShell {
  margin-top: 0 !important;
}


/*
  Chat / Notes 是 fixed 弹出页，会脱离文档流。
  所以它们需要手动从按钮下面开始。
*/
.overlay-page {
  top: var(--tutu-panel-offset) !important;
  bottom: 0 !important;
  height: auto !important;
}

/* 收起时隐藏主页面 */
body.tutu-collapsed #appShell {
  display: none !important;
}

/* 收起时隐藏弹出页 */
body.tutu-collapsed .overlay-page {
  display: none !important;
}

/* 收起时只保留按钮区域 */
body.tutu-collapsed {
  height: var(--tutu-panel-offset) !important;
  min-height: var(--tutu-panel-offset) !important;
  overflow: hidden !important;
  background: transparent !important;
}

body.tutu-collapsed.overlay-open #appShell {
  display: none !important;
  visibility: hidden !important;
}


</style>
</head>

