var C = window.CONFIG;
if (!C) C = {};
/* 顶部收起按钮配置 */
(function initTutuPanelConfig() {
  var cfg = (C && C.panelToggle) || {};

  var defaults = {
    enabled: true,
    icon: 'https://s3.bmp.ovh/2026/07/05/CfXtx4l1.png',
    size: 92,
    topGap: 4,
    pageGap: 8,
    defaultCollapsed: true,
    hideOnOverlay: false
  };

  Object.keys(defaults).forEach(function(k) {
    if (cfg[k] === undefined || cfg[k] === null || cfg[k] === '') {
      cfg[k] = defaults[k];
    }
  });

  C.panelToggle = cfg;

  var root = document.documentElement;
  var btn = document.getElementById('tutuPanelToggle');
  var img = document.querySelector('#tutuPanelToggle img');

  function num(v, fallback) {
    var n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  }

  root.style.setProperty('--tutu-toggle-base-size', num(cfg.size, 92) + 'px');
  root.style.setProperty('--tutu-toggle-base-top-gap', num(cfg.topGap, 4) + 'px');
  root.style.setProperty('--tutu-toggle-base-page-gap', num(cfg.pageGap, 8) + 'px');

  if (img) {
    img.src = cfg.icon || defaults.icon;
  }

  if (btn && cfg.enabled === false) {
    btn.style.display = 'none';
  }

  document.body.classList.toggle(
    'tutu-hide-toggle-on-overlay',
    !!cfg.hideOnOverlay
  );
})();
/* ═══════════════════════════════════════
   REGION: 顶部收起按钮配置
═══════════════════════════════════════ */
(function initTutuPanelConfig() {
  var cfg = (C && C.panelToggle) || {};

  var defaults = {
    enabled: true,
    icon: 'https://s3.bmp.ovh/2026/07/05/CfXtx4l1.png',
    size: 92,
    topGap: 4,
    pageGap: 8,
    defaultCollapsed: true,
    hideOnOverlay: false
  };

  Object.keys(defaults).forEach(function(k) {
    if (cfg[k] === undefined || cfg[k] === null || cfg[k] === '') {
      cfg[k] = defaults[k];
    }
  });

  C.panelToggle = cfg;

  var root = document.documentElement;
  var btn = document.getElementById('tutuPanelToggle');
  var img = document.getElementById('tutuPanelToggleImg');

  function num(v, fallback) {
    var n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  }

  if (cfg.enabled === false) {
    if (btn) btn.style.display = 'none';
    root.style.setProperty('--tutu-toggle-size', '0px');
    root.style.setProperty('--tutu-toggle-top-gap', '0px');
    root.style.setProperty('--tutu-toggle-page-gap', '0px');
    root.style.setProperty('--tutu-panel-offset', '0px');
    document.body.classList.remove('tutu-hide-toggle-on-overlay');
    return;
  }

  root.style.setProperty('--tutu-toggle-size', num(cfg.size, 92) + 'px');
  root.style.setProperty('--tutu-toggle-top-gap', num(cfg.topGap, 4) + 'px');
  root.style.setProperty('--tutu-toggle-page-gap', num(cfg.pageGap, 8) + 'px');

  if (img) {
    img.src = cfg.icon || defaults.icon;
  }

  document.body.classList.toggle(
    'tutu-hide-toggle-on-overlay',
    !!cfg.hideOnOverlay
  );
})();


function getRawData(id) {
  var el = document.getElementById(id);
  return el ? el.value : '';
}

var RAW_CHAT = getRawData('rawChatData');
var RAW_NOTES = getRawData('rawNotesData');
var RAW_TIME = getRawData('rawTimeData');

if (C.messages && C.messages[0]) C.messages[0].time = RAW_TIME;
if (C.messages && C.messages[1]) C.messages[1].time = RAW_TIME;
if (C.chat) C.chat.content = RAW_CHAT;


/* --- HTML转义 --- */
function esc(str) {
  if (str == null) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/* --- 心情表情包随机 --- */
function getMoodImage(keyword) {
  var lib = C.moodLibrary || {};
  var word = String(keyword || '').trim();
  var keys = Object.keys(lib);

  function getImages(value) {
    var images = Array.isArray(value)
      ? value
      : typeof value === 'string'
        ? [value]
        : [];

    return images
      .filter(function(image) {
        return typeof image === 'string' && image.trim();
      })
      .map(function(image) {
        return image.trim();
      });
  }

  function pick(images) {
    return images.length
      ? images[Math.floor(Math.random() * images.length)]
      : '';
  }

  // 优先匹配完整分类名称，兼容原来的分类。
  if (Object.prototype.hasOwnProperty.call(lib, word)) {
    var exactImages = getImages(lib[word]);

    if (exactImages.length) {
      return pick(exactImages);
    }
  }

  // 分类名称支持英文逗号、中文逗号、顿号。
  var matchedImages = [];

  if (word) {
    keys.forEach(function(key) {
      var aliases = key.split(/[,，、]/).map(function(name) {
        return name.trim();
      }).filter(Boolean);

      if (aliases.indexOf(word) !== -1) {
        matchedImages = matchedImages.concat(
          getImages(lib[key])
        );
      }
    });
  }

  if (matchedImages.length) {
    return pick(Array.from(new Set(matchedImages)));
  }

  // 没有匹配到时，保留原来的全图库随机逻辑。
  var all = [];

  keys.forEach(function(key) {
    all = all.concat(getImages(lib[key]));
  });

  return pick(Array.from(new Set(all)));
}

/* --- 时间同步系统 --- */

function parseTimeSource(timeStr) {
  var h, m;
  if (!timeStr) {
    var now = new Date();
    h = now.getHours();
    m = now.getMinutes();
  } else {
    var match = String(timeStr).trim().match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/i);
    if (match) {
      h = parseInt(match[1], 10);
      m = parseInt(match[2], 10);
      if (match[3] && match[3].toUpperCase() === 'PM' && h < 12) h += 12;
      if (match[3] && match[3].toUpperCase() === 'AM' && h === 12) h = 0;
    } else {
      var now2 = new Date();
      h = now2.getHours();
      m = now2.getMinutes();
    }
  }
  return { h: h, m: m };
}


function padTwo(n) { return String(n).padStart(2, '0'); }

function formatMsgTime(h, m) {
  var ampm = h >= 12 ? 'PM' : 'AM';
  var h12 = h % 12 || 12;
  return h12 + ':' + padTwo(m) + ' ' + ampm;
}

function formatNoteDate(h, m) {
  var d = new Date();
  return d.getFullYear() + '年' + (d.getMonth() + 1) + '月' + d.getDate() + '日 '
    + padTwo(h) + ':' + padTwo(m);
}

function formatChatDate(h, m) {
  var d = new Date();
  var days = ['周日','周一','周二','周三','周四','周五','周六'];
  return (d.getMonth() + 1) + '月' + d.getDate() + '日 '
    + days[d.getDay()] + padTwo(h) + ':' + padTwo(m);
}

function formatReadReceipt(h, m) {
  return padTwo(h) + ':' + padTwo(m);
}

function formatTweetMeta(h, m) {
  var d = new Date();
  return padTwo(h) + ':' + padTwo(m) + '· '
    + d.getFullYear() + '/' + (d.getMonth() + 1) + '/' + d.getDate();
}

/* --- 获取同步后的所有时间格式 --- */

function getAllTimes() {
  var raw = RAW_TIME || '';

  if (C.messages && C.messages[0] && C.messages[0].time) {
    raw = C.messages[0].time;
  }

  var t = parseTimeSource(raw);
  return {
    msgTime: formatMsgTime(t.h, t.m),
    chatDate: formatChatDate(t.h, t.m),
    readReceipt: formatReadReceipt(t.h, t.m),
    noteDate: formatNoteDate(t.h, t.m),
    tweetMeta: formatTweetMeta(t.h, t.m)
  };
}


