  function renderNotesContent(input) {
    document.getElementById('noteDateLine').textContent = times.noteDate;
    var container = document.getElementById('modulesContainer');
    var html = '', moduleCount = 0;

    var diaryMatch = input.match(/\[diary\]([\s\S]*?)\[\/diary\]/);
    var todoMatch = input.match(/\[todo\]([\s\S]*?)\[\/todo\]/);
    var moodMatch = input.match(/\[mood\]([\s\S]*?)\[\/mood\]/);
    var translateMatch = input.match(/\[translate\]([\s\S]*?)\[\/translate\]/);
    var tweetMatch = input.match(/\[tweet\]([\s\S]*?)\[\/tweet\]/);

    var order = notes.moduleOrder || ['mood', 'todo', 'translate', 'diary', 'tweet'];

    var modules = {
      diary: function() { return diaryMatch ? parseDiary(diaryMatch[1]) : ''; },
      todo: function() { return todoMatch ? parseTodo(todoMatch[1]) : ''; },
      mood: function() { return moodMatch ? parseMood(moodMatch[1]) : ''; },
      tweet: function() { return tweetMatch ? parseTweet(tweetMatch[1]) : ''; },
      translate: function() {
        if (!translateMatch) return '';
        var tResult = parseTranslate(translateMatch[1]);
        if (tResult) {
          translateData = tResult.data;
          tCurrentIndex = 0;
          return tResult.html;
        }
        return '';
      }
    };

    order.forEach(function(key) {
      var result = modules[key] ? modules[key]() : '';
      if (result) {
        if (moduleCount > 0) html += '<div class="note-divider"></div>';
        html += result;
        moduleCount++;
      }
    });

    container.innerHTML = html;

    if (translateData && translateData.length > 0) {
      renderTranslateCard();
      bindTranslateSwitch();
    }

    bindInteractions();
    notesUpdateAll();
  }

