/* ═══════════════════════════════════════
   REGION: 统一等比缩放【按钮在文档流版】
   ═══════════════════════════════════════ */
(function initScale() {
  var DESIGN_W = 430;
  var DESIGN_H = 800;

  function getScale() {
    return Math.min(1, window.innerWidth / DESIGN_W);
  }

  function getPanelOffset() {
    return parseFloat(
      getComputedStyle(document.documentElement).getPropertyValue('--tutu-panel-offset')
    ) || 0;
  }

  function scaleMainPage() {
    var shell = document.getElementById('appShell');
    var page = document.getElementById('page-messages');
    if (!shell || !page) return;

    var s = getScale();

    shell.style.position = 'relative';
    shell.style.left = '50%';
    shell.style.width = DESIGN_W + 'px';

    /*
      重点：
      按钮现在已经在文档流里占了上方空间，
      所以 appShell 不要再 margin-top。
    */
    shell.style.margin = '0';

    shell.style.transformOrigin = 'top center';
    shell.style.transform = 'translateX(-50%) scale(' + s + ')';

    if (document.body.classList.contains('tutu-collapsed')) {
      shell.style.height = '0px';
    } else if (document.body.classList.contains('overlay-open')) {
      shell.style.height = (DESIGN_H * s) + 'px';
    } else {
      shell.style.height = (page.offsetHeight * s) + 'px';
    }
  }

  function scaleOverlayPages() {
    var s = getScale();

    document.querySelectorAll('.overlay-page').forEach(function(page) {
      page.style.maxHeight = '';
      page.style.overflow = 'hidden';
    });

    document.querySelectorAll('.overlay-stage').forEach(function(stage) {
      stage.style.transformOrigin = 'top center';
      stage.style.transform = 'scale(' + s + ')';
      stage.style.width = DESIGN_W + 'px';
      stage.style.height = DESIGN_H + 'px';
    });

    /*
      重点：
      按钮已经自己占据高度了。
      所以 overlay-doc-height 只需要撑出 overlay 本身的高度，
      不要再加 offset，否则会多一截空白。
    */
    if (document.body.classList.contains('tutu-collapsed')) {
      document.body.style.setProperty('--overlay-doc-height', '0px');
    } else {
      document.body.style.setProperty('--overlay-doc-height', (DESIGN_H * s) + 'px');
    }
  }

function doScale() {
  var s = getScale();
  document.documentElement.style.setProperty('--tutu-ui-scale', s);

  scaleMainPage();
  scaleOverlayPages();
}


  window.addEventListener('resize', doScale);

  if (window.visualViewport) {
    window.visualViewport.addEventListener('resize', doScale);
  }

  window.tutuDoScale = doScale;

  doScale();
  setTimeout(doScale, 50);
  setTimeout(doScale, 300);
})();

