  requestAnimationFrame(function() {
    requestAnimationFrame(function() {
      target.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
        inline: 'center'
      });
    });
  });
}

function setCollapsed(isCollapsed) {
  if (isCollapsed) {
    forceCloseOverlayPages();
  }

  document.body.classList.toggle('tutu-collapsed', isCollapsed);

  btn.setAttribute('aria-expanded', isCollapsed ? 'false' : 'true');
  btn.title = isCollapsed ? '展开' : '收起';

  refreshLayout();

  // 展开后自动滚到页面正中心
  if (!isCollapsed) {
    setTimeout(scrollPanelToCenter, 80);
  }
}

  function togglePanel(e) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
      if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    }

    if (isBusy) return;
    isBusy = true;

    var nowCollapsed = document.body.classList.contains('tutu-collapsed');
    setCollapsed(!nowCollapsed);

    setTimeout(function() {
      isBusy = false;
    }, 180);
  }

  /*
    用 pointerup 就够了，不要 click + touchend 两个一起绑，
    不然有些手机环境会触发两次，导致展开后又立刻收起。
  */
  btn.addEventListener('pointerup', togglePanel, true);

/* 每次打开是否默认收起：由 CONFIG.panelToggle.defaultCollapsed 控制 */
var panelCfg = (C && C.panelToggle) || {};

if (panelCfg.enabled === false) {
  document.body.classList.remove('tutu-collapsed');
  btn.style.display = 'none';
  return;
}

setCollapsed(panelCfg.defaultCollapsed !== false);

})();


